import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  Cake,
  ChevronLeft,
  ChevronRight,
  Mail,
  Lock,
  Eye,
  EyeOff,
  Sparkles,
  Truck,
  Clock,
} from "lucide-react";

const bakeryImages = [
  {
    image:
      "https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1000&q=85",
    title: "Freshly Baked Cakes",
    description: "Made fresh with love every single day.",
  },
  {
    image:
      "https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=1000&q=85",
    title: "Delicious Pastries",
    description: "Crispy, creamy and perfect for every moment.",
  },
  {
    image:
      "https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=1000&q=85",
    title: "Fresh Bakery Items",
    description: "Quality ingredients baked to perfection.",
  },
];

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [showPassword, setShowPassword] = useState(false);

  const { login } = useAuth();
  const nav = useNavigate();

  // Auto-scroll images every 3 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % bakeryImages.length);
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % bakeryImages.length);
  };

  const prevSlide = () => {
    setCurrentSlide(
      (prev) => (prev - 1 + bakeryImages.length) % bakeryImages.length
    );
  };

  const submit = async (e) => {
    e.preventDefault();

    setLoading(true);

    try {
      const r = await login(email, password);

      if (r.ok) {
        nav(r.user.role === "admin" ? "/admin" : "/");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="min-h-screen relative overflow-hidden"
      style={{
        backgroundImage: `
          linear-gradient(
            135deg,
            rgba(255, 248, 238, 0.96),
            rgba(255, 243, 224, 0.92)
          ),
          url("https://images.unsplash.com/photo-1558961363-fa8fdf82db35?auto=format&fit=crop&w=2000&q=80")
        `,
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      {/* Decorative background circles */}
      <div className="absolute -top-32 -left-32 w-80 h-80 bg-[#06d2d9]/10 rounded-full blur-3xl" />
      <div className="absolute -bottom-32 -right-32 w-96 h-96 bg-[#f4b183]/20 rounded-full blur-3xl" />

      <div className="relative min-h-screen flex items-center justify-center px-4 py-8 lg:px-8">
        <div className="w-full max-w-7xl">

          {/* Main Login Container */}
          <div className="grid lg:grid-cols-2 bg-white/90 backdrop-blur-xl rounded-[32px] shadow-2xl overflow-hidden border border-white/70">

            {/* =====================================================
                LEFT SIDE - IMAGE CAROUSEL
            ====================================================== */}
            <div className="relative min-h-[550px] lg:min-h-[700px] flex flex-col justify-center overflow-hidden bg-gradient-to-br from-[#fff1dd] to-[#f8d9b3] p-6 sm:p-10 lg:p-12">

              {/* Decorative shapes */}
              <div className="absolute top-0 left-0 w-40 h-40 bg-white/30 rounded-full -translate-x-20 -translate-y-20" />
              <div className="absolute bottom-0 right-0 w-64 h-64 bg-[#06d2d9]/10 rounded-full translate-x-20 translate-y-20" />

              {/* Heading */}
              <div className="relative z-10 text-center mb-8">
                <div className="flex items-center justify-center gap-2 mb-3">
                  <Sparkles className="w-5 h-5 text-[#06d2d9]" />
                  <span className="text-[#06d2d9] font-semibold tracking-wide">
                    SLV BAKERY
                  </span>
                  <Sparkles className="w-5 h-5 text-[#06d2d9]" />
                </div>

                <h2 className="font-display text-3xl sm:text-4xl lg:text-5xl font-bold text-[#5C4A3D]">
                  Freshly Baked
                </h2>

                <h3 className="font-display text-2xl sm:text-3xl lg:text-4xl font-bold text-[#06aeb4] mt-1">
                  Happiness Delivered
                </h3>

                <p className="text-[#795548] mt-3 max-w-md mx-auto">
                  Taste the freshness, enjoy the sweetness and make every
                  moment special.
                </p>
              </div>

              {/* Image Carousel */}
              <div className="relative z-10 max-w-xl w-full mx-auto">

                {/* Main Image */}
                <div className="relative h-[300px] sm:h-[350px] lg:h-[390px] rounded-[28px] overflow-hidden shadow-2xl border-4 border-white">

                  {bakeryImages.map((item, index) => (
                    <img
                      key={item.image}
                      src={item.image}
                      alt={item.title}
                      className={`absolute inset-0 w-full h-full object-cover transition-all duration-700 ${
                        index === currentSlide
                          ? "opacity-100 scale-100"
                          : "opacity-0 scale-105"
                      }`}
                    />
                  ))}

                  {/* Image overlay */}
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent p-6">
                    <h4 className="text-white text-2xl font-bold">
                      {bakeryImages[currentSlide].title}
                    </h4>

                    <p className="text-white/90 text-sm mt-1">
                      {bakeryImages[currentSlide].description}
                    </p>
                  </div>

                  {/* Previous Button */}
                  <button
                    type="button"
                    onClick={prevSlide}
                    className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-white/90 hover:bg-white flex items-center justify-center shadow-lg transition"
                  >
                    <ChevronLeft className="w-5 h-5 text-[#5C4A3D]" />
                  </button>

                  {/* Next Button */}
                  <button
                    type="button"
                    onClick={nextSlide}
                    className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-white/90 hover:bg-white flex items-center justify-center shadow-lg transition"
                  >
                    <ChevronRight className="w-5 h-5 text-[#5C4A3D]" />
                  </button>
                </div>

                {/* Slider Dots */}
                <div className="flex justify-center gap-2 mt-5">
                  {bakeryImages.map((_, index) => (
                    <button
                      key={index}
                      type="button"
                      onClick={() => setCurrentSlide(index)}
                      className={`h-2.5 rounded-full transition-all duration-300 ${
                        index === currentSlide
                          ? "w-8 bg-[#06d2d9]"
                          : "w-2.5 bg-[#5C4A3D]/30"
                      }`}
                    />
                  ))}
                </div>
              </div>

              {/* Features */}
              <div className="relative z-10 grid grid-cols-3 gap-3 max-w-xl mx-auto w-full mt-8">

                <div className="text-center">
                  <div className="w-11 h-11 mx-auto rounded-full bg-white flex items-center justify-center shadow-md">
                    <Cake className="w-5 h-5 text-[#06d2d9]" />
                  </div>

                  <p className="text-xs sm:text-sm font-semibold text-[#5C4A3D] mt-2">
                    Fresh Ingredients
                  </p>

                  <p className="hidden sm:block text-xs text-[#795548] mt-1">
                    Premium quality
                  </p>
                </div>

                <div className="text-center">
                  <div className="w-11 h-11 mx-auto rounded-full bg-white flex items-center justify-center shadow-md">
                    <Clock className="w-5 h-5 text-[#06d2d9]" />
                  </div>

                  <p className="text-xs sm:text-sm font-semibold text-[#5C4A3D] mt-2">
                    Baked Daily
                  </p>

                  <p className="hidden sm:block text-xs text-[#795548] mt-1">
                    Made fresh daily
                  </p>
                </div>

                <div className="text-center">
                  <div className="w-11 h-11 mx-auto rounded-full bg-white flex items-center justify-center shadow-md">
                    <Truck className="w-5 h-5 text-[#06d2d9]" />
                  </div>

                  <p className="text-xs sm:text-sm font-semibold text-[#5C4A3D] mt-2">
                    Fast Delivery
                  </p>

                  <p className="hidden sm:block text-xs text-[#795548] mt-1">
                    To your doorstep
                  </p>
                </div>

              </div>
            </div>

            {/* =====================================================
                RIGHT SIDE - LOGIN FORM
            ====================================================== */}
            <div className="flex items-center justify-center p-6 sm:p-10 lg:p-16 bg-white/95">

              <div className="w-full max-w-md">

                {/* Logo */}
                <div className="text-center mb-8">

                  <div className="w-16 h-16 mx-auto rounded-2xl bg-[#06d2d9] flex items-center justify-center shadow-lg shadow-[#06d2d9]/20">
                    <Cake className="w-8 h-8 text-white" />
                  </div>

                  <h1 className="font-display text-3xl sm:text-4xl font-bold text-[#3E3028] mt-5">
                    Welcome Back
                  </h1>

                  <p className="text-[#5C4A3D] text-sm mt-2">
                    Login to continue your bakery journey
                  </p>

                </div>

                {/* Form */}
                <form
                  onSubmit={submit}
                  className="space-y-5"
                  data-testid="login-page"
                >

                  {/* Email */}
                  <div>
                    <Label
                      htmlFor="email"
                      className="text-[#3E3028] font-semibold"
                    >
                      Email
                    </Label>

                    <div className="relative mt-2">
                      <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8D7A6D]" />

                      <Input
                        id="email"
                        type="email"
                        placeholder="Enter your email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        required
                        data-testid="login-email"
                        className="h-12 pl-12 pr-4 rounded-xl border-[#E6DFD5] focus:border-[#06d2d9] focus:ring-[#06d2d9]"
                      />
                    </div>
                  </div>

                  {/* Password */}
                  <div>
                    <div className="flex justify-between items-center">
                      <Label
                        htmlFor="password"
                        className="text-[#3E3028] font-semibold"
                      >
                        Password
                      </Label>
                    </div>

                    <div className="relative mt-2">

                      <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8D7A6D]" />

                      <Input
                        id="password"
                        type={showPassword ? "text" : "password"}
                        placeholder="Enter your password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        data-testid="login-password"
                        className="h-12 pl-12 pr-12 rounded-xl border-[#E6DFD5] focus:border-[#06d2d9] focus:ring-[#06d2d9]"
                      />

                      <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute right-4 top-1/2 -translate-y-1/2 text-[#8D7A6D] hover:text-[#06d2d9]"
                      >
                        {showPassword ? (
                          <EyeOff className="w-5 h-5" />
                        ) : (
                          <Eye className="w-5 h-5" />
                        )}
                      </button>

                    </div>
                  </div>

                  {/* Forgot Password */}
                  <div className="flex justify-end">
                    <Link
                      to="/forgot-password"
                      className="text-sm text-[#06aeb4] hover:text-[#058c91] hover:underline font-medium"
                    >
                      Forgot Password?
                    </Link>
                  </div>

                  {/* Sign In */}
                  <Button
                    type="submit"
                    disabled={loading}
                    className="w-full h-12 rounded-xl bg-[#06d2d9] hover:bg-[#05b8be] text-white font-semibold text-base shadow-lg shadow-[#06d2d9]/20 transition-all"
                    data-testid="login-submit"
                  >
                    {loading ? "Signing in..." : "Sign In"}
                  </Button>

                  {/* Divider */}
                  <div className="flex items-center gap-4 py-2">
                    <div className="flex-1 h-px bg-[#E6DFD5]" />
                    <span className="text-xs text-[#8D7A6D]">OR</span>
                    <div className="flex-1 h-px bg-[#E6DFD5]" />
                  </div>

                  {/* Signup */}
                  <div className="text-center text-sm text-[#5C4A3D]">
                    New here?{" "}
                    <Link
                      to="/signup"
                      className="text-[#06aeb4] font-semibold hover:underline"
                    >
                      Create account
                    </Link>
                  </div>

                </form>

                {/* Bottom Text */}
                <div className="text-center mt-8">
                  <p className="text-xs text-[#8D7A6D]">
                    Freshly baked with ❤️ by SLV Bakery
                  </p>
                </div>

              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}
